  let out = '';
  for (let i = 0; i < 8; i++) {
    if (mask & (1 << i)) out += LETTERS[i];
  }
  return out;
}

function grant(mask, other) {
  return (mask | other) & 0xff;
}

function revoke(mask, other) {
  return mask & ~other & 0xff;
}

function toggle(mask, other) {
  return (mask ^ other) & 0xff;
}

function rotl8(mask, k) {
  const s = ((k % 8) + 8) % 8;
  return ((mask << s) | (mask >> (8 - s))) & 0xff;
}

function popcount(mask) {
  let n = 0;
  for (let i = 0; i < 8; i++) {
    if (mask & (1 << i)) n++;
  }
  return n;
